// --- MODULE: moderation.js ---
// ==============================================================================
// src/moderation.js - Moderation Engine (Blacklist, Flood, Dangerous Files, Avatar & Regex Keywords)
// ==============================================================================
import {
  cachedKvGetJson,
  cachedKvPutJson,
  getMemoryCache,
  setMemoryCache,
  kvGetJson,
  kvPutJson,
  incrementStat,
  fetchKeywordDb,
} from './cache.js';
function normalizeMessageText(text = '') {
  if (!text || typeof text !== 'string') return '';
  return text
    // Strip zero-width, invisible & direction marks
    .replace(/[\u200B-\u200F\uFEFF\u2060\u180E\u00AD]/g, '')
    // Convert full-width ASCII to standard half-width
    .replace(/[\uFF01-\uFF5E]/g, (ch) => String.fromCharCode(ch.charCodeAt(0) - 0xfee0))
    // Convert full-width space to standard space
    .replace(/\u3000/g, ' ')
    // Normalize multi-whitespace
    .replace(/\s+/g, ' ')
    .trim();
}
function parseKeywordRule(rawRule) {
  const raw = String(rawRule || '').trim();
  if (!raw) return null;

  const regexMatch = raw.match(/^\/(.+)\/([a-z]*)$/i);
  if (regexMatch) {
    const [, pattern, flags] = regexMatch;
    try {
      const safeFlags = flags.includes('i') ? flags : `${flags}i`;
      const regex = new RegExp(pattern, safeFlags);
      return {
        raw,
        isRegex: true,
        regex,
      };
    } catch (err) {
      console.log(JSON.stringify({ error: 'invalid-regex-rule', raw, message: err.message }));
      return {
        raw,
        isRegex: false,
        text: raw.toLowerCase(),
      };
    }
  }

  return {
    raw,
    isRegex: false,
    text: raw.toLowerCase(),
  };
}
async function isUserBlocked(chatId) {
  return cachedKvGetJson(`isblocked-${chatId}`, 60000, false);
}
async function setUserBlocked(chatId, blocked) {
  return cachedKvPutJson(`isblocked-${chatId}`, blocked, {}, 60000);
}
async function checkFloodLimit(chatId, config) {
  if (!config.flood_protect) return { blocked: false };

  const now = Date.now();
  const muteKey = `flood-mute-${chatId}`;
  const muteUntil = Number(getMemoryCache(muteKey) || (await nfd.get(muteKey)) || 0);
  if (muteUntil > now) {
    return { blocked: true, remainingSeconds: Math.ceil((muteUntil - now) / 1000) };
  }

  const windowMs = (config.flood_window_seconds || 10) * 1000;
  const historyKey = `flood-history-${chatId}`;
  const history = asArray(getMemoryCache(historyKey) || []);
  const validHistory = history.filter((ts) => now - ts < windowMs);
  validHistory.push(now);
  setMemoryCache(historyKey, validHistory, windowMs);

  if (validHistory.length > (config.flood_limit || 5)) {
    const muteSeconds = config.flood_mute_seconds || 60;
    const muteExpires = now + muteSeconds * 1000;
    setMemoryCache(muteKey, muteExpires, muteSeconds * 1000);
    await nfd.put(muteKey, String(muteExpires), { expirationTtl: muteSeconds });
    await incrementStat('flood-blocked');
    return { blocked: true, remainingSeconds: muteSeconds, triggeredNow: true };
  }

  return { blocked: false };
}
function isDangerousDocument(message) {
  const doc = message?.document;
  if (!doc || !doc.file_name) return false;
  const fileName = doc.file_name.toLowerCase();
  const dangerousExts = ['.exe', '.bat', '.apk', '.cmd', '.vbs', '.ps1', '.scr', '.sh', '.jar', '.msi', '.dll', '.pif'];
  return dangerousExts.some((ext) => fileName.endsWith(ext));
}
async function checkUserHasPhoto(userId) {
  const numericId = Number(userId);
  if (!numericId || Number.isNaN(numericId) || numericId <= 0) return true;

  const key = `has-photo-${numericId}`;
  const cached = getMemoryCache(key);
  if (typeof cached === 'boolean') return cached;

  const kvVal = await kvGetJson(key, null);
  if (typeof kvVal === 'boolean') {
    setMemoryCache(key, kvVal, kvVal ? 3600000 : 300000);
    return kvVal;
  }

  try {
    const res = await requestTelegram('getUserProfilePhotos', { user_id: numericId, limit: 1 });
    if (!res.ok) return true; // fail open on error
    const hasPhoto = Boolean(res.result && Number(res.result.total_count) > 0);
    const ttl = hasPhoto ? 3600 : 300;
    setMemoryCache(key, hasPhoto, ttl * 1000);
    await kvPutJson(key, hasPhoto, { expirationTtl: ttl });
    return hasPhoto;
  } catch (e) {
    console.log(JSON.stringify({ error: 'checkUserHasPhoto-failed', userId, message: e.message }));
    return true;
  }
}
async function getKeywordRules() {
  const cacheKey = 'merged-keyword-rules';
  const cached = getMemoryCache(cacheKey);
  if (cached) return cached;

  const fromKv = await cachedKvGetJson('blocked-keywords', 120000, []);
  const fromDb = await fetchKeywordDb();
  const rawList = Array.from(new Set([...fromDb, ...asArray(fromKv)]));

  const parsedRules = rawList.map(parseKeywordRule).filter(Boolean);
  setMemoryCache(cacheKey, parsedRules, 60000);
  return parsedRules;
}
async function findBlockedKeyword(message) {
  const rawContent = getMessageText(message);
  if (!rawContent) return null;

  const normalized = normalizeMessageText(rawContent);
  const lowerNormalized = normalized.toLowerCase();
  const rules = await getKeywordRules();

  for (const rule of rules) {
    if (rule.isRegex && rule.regex) {
      const match = normalized.match(rule.regex);
      if (match) {
        return {
          matched: true,
          rule: rule.raw,
          snippet: match[0],
        };
      }
    } else if (rule.text) {
      if (lowerNormalized.includes(rule.text)) {
        return {
          matched: true,
          rule: rule.raw,
          snippet: rule.raw,
        };
      }
    }
  }

  return null;
}
async function recordKeywordViolation(message, keyword) {
  const chatId = String(message.chat.id);
  const key = `keyword-violation-${chatId}`;
  const current = await kvGetJson(key, { count: 0, expiresAt: 0 });
  const now = Date.now();
  const count = current.expiresAt > now ? Number(current.count || 0) + 1 : 1;
  const ttl = getKeywordViolationTtl();
  const record = {
    count,
    lastKeyword: keyword,
    updatedAt: now,
    expiresAt: now + ttl * 1000,
  };
  await kvPutJson(key, record, { expirationTtl: ttl });
  return record;
}
async function notifyKeywordBlocked(message, matchResult, violation, config) {
  await incrementStat('keyword-blocked');
  if (!config.notice_admin) return null;
  const alertChatId = config.alert_chat_id || getAdminUid();
  if (!alertChatId) return null;

  const ruleName = typeof matchResult === 'string' ? matchResult : matchResult.rule;
  const snippet = typeof matchResult === 'object' && matchResult?.snippet ? matchResult.snippet : '';

  const lines = [
    '*人偶拦下了一条留言*',
    mdLine('触发规则', ruleName),
  ];

  if (snippet && snippet !== ruleName) {
    lines.push(mdLine('命中切片', snippet));
  }

  lines.push(
    mdLine('累计次数', violation.count),
    mdLine('用户ID', message.chat.id),
    mdLine('客人', buildUserName(message.from || {})),
  );

  if (config.auto_block && violation.count >= config.violation_limit) {
    lines.push(mdLine('处理', '已自动拉入黑名单'));
  }
  const extra = config.alert_thread_id ? { message_thread_id: config.alert_thread_id } : {};
  return sendMarkdown(alertChatId, lines.join('\n'), extra);
}

// --- MODULE: pipeline.js ---
// ==============================================================================
// src/pipeline.js - Message Buffering, Delayed Aggregation & Batch Forwarding
// ==============================================================================

import {
  MESSAGE_MAP_TTL,
  NOTIFY_INTERVAL,
  DEFAULT_NOTIFICATION,
  getAdminUid,
  getUserAckCooldownMs,
  getCommandWarningCooldownMs,
  getNotificationUrl,
  asArray,
  sleep,
} from './config.js';
import {
  cachedKvGetJson,
  cachedKvPutJson,
  getMemoryCache,
  setMemoryCache,
  kvGetJson,
  kvPutJson,
  getRuntimeConfig,
  incrementStat,
  sendCooldownPlainText,
  isFraud,
  fetchTextOrDefault,
  getGuestTag,
  trackGuestProfile,
  getGuestTopicId,
  setGuestTopicId,
  getGuestIdByTopic,
} from './cache.js';
import {
  sendMarkdown,
  copyMessage,
  forwardMessage,
  mdLine,
  buildMessageInfo,
  buildUserName,
  adminMessageKeyboard,
  createForumTopic,
} from './telegram.js';
import {
  isUserBlocked,
  setUserBlocked,
  checkUserHasPhoto,
  findBlockedKeyword,
  recordKeywordViolation,
  notifyKeywordBlocked,
  checkFloodLimit,
  isDangerousDocument,
} from './moderation.js';
async function rememberMessageMap(adminMessageId, guestChatId) {
  setMemoryCache(`msg-map-${adminMessageId}`, String(guestChatId), 3600000);
  return kvPutJson(`msg-map-${adminMessageId}`, String(guestChatId), {
    expirationTtl: MESSAGE_MAP_TTL,
  });
}
async function getMappedGuestId(adminMessage) {
  // 1. Check if message is sent inside a Forum Topic
  const threadId = adminMessage?.message_thread_id;
  if (threadId) {
    const topicGuestId = await getGuestIdByTopic(threadId);
    if (topicGuestId) return topicGuestId;
  }

  // 2. Check reply message ID mapping
  const replyMessageId = adminMessage?.reply_to_message?.message_id;
  if (!replyMessageId) return null;
  const cached = getMemoryCache(`msg-map-${replyMessageId}`);
  if (cached) return cached;
  return kvGetJson(`msg-map-${replyMessageId}`, null);
}
async function handleGuestMessage(message) {
  const chatId = String(message.chat.id);
  const config = await getRuntimeConfig();
  const warningCooldown = getCommandWarningCooldownMs();

  // Parallelize analytics, profile update and user check
  const [isBlocked] = await Promise.all([
    isUserBlocked(chatId),
    incrementStat('guest-message'),
    trackGuestProfile(message),
  ]);

  if (isBlocked) {
    await incrementStat('blocked-user-message');
    return sendCooldownPlainText(chatId, `blocked-notice-${chatId}`, '这里暂时不能继续留言了喵。', warningCooldown);
  }

  // Anti-Flood / Rate Limiting
  const floodCheck = await checkFloodLimit(chatId, config);
  if (floodCheck.blocked) {
    return sendCooldownPlainText(
      chatId,
      `flood-notice-${chatId}`,
      `发送消息太频繁啦，请休息 ${floodCheck.remainingSeconds || 60} 秒后再试喵。`,
      warningCooldown,
    );
  }

  // Dangerous document filter
  if (config.block_executables && isDangerousDocument(message)) {
    await incrementStat('executable-blocked');
    return sendCooldownPlainText(
      chatId,
      `exec-block-${chatId}`,
      '抱歉，为了系统安全，不能转达可执行程序或安装包文件喵。',
      warningCooldown,
    );
  }

  if (config.req_username && !message.from?.username) {
    await incrementStat('no-username-blocked');
    return sendCooldownPlainText(
      chatId,
      `no-username-${chatId}`,
      '请先在 Telegram 设置用户名（Username / @xxx）后再留言喵。',
      warningCooldown,
    );
  }

  if (config.req_photo) {
    const userId = message.from?.id || message.chat.id;
    const hasPhoto = await checkUserHasPhoto(userId);
    if (!hasPhoto) {
      await incrementStat('no-photo-blocked');
      return sendCooldownPlainText(
        chatId,
        `no-photo-${chatId}`,
        '请先在 Telegram 设置个人头像后再留言喵。',
        warningCooldown,
      );
    }
  }

  if (config.delay_seconds > 0) {
    return handleDelayedGuestMessage(message, config);
  }

  return processGuestMessageBatch([message], config);
}
async function handleDelayedGuestMessage(message, config) {
  const chatId = String(message.chat.id);
  const batchKey = `pending-msgs-${chatId}`;
  const tokenKey = `pending-token-${chatId}`;

  const current = asArray(await kvGetJson(batchKey, []));
  if (!current.some((m) => m.message_id === message.message_id)) {
    current.push(message);
  }

  const token = `${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
  await kvPutJson(batchKey, current, { expirationTtl: 300 });
  await kvPutJson(tokenKey, token, { expirationTtl: 300 });

  if (current.length >= 10) {
    await kvPutJson(batchKey, null, { expirationTtl: 60 });
    await kvPutJson(tokenKey, null, { expirationTtl: 60 });
    return processGuestMessageBatch(current, config);
  }

  await sleep(config.delay_seconds * 1000);

  const activeToken = await kvGetJson(tokenKey, null);
  if (activeToken !== token) {
    return;
  }

  const finalBatch = asArray(await kvGetJson(batchKey, []));
  await kvPutJson(batchKey, null, { expirationTtl: 60 });
  await kvPutJson(tokenKey, null, { expirationTtl: 60 });

  if (!finalBatch.length) return;
  return processGuestMessageBatch(finalBatch, config);
}
async function processGuestMessageBatch(messages, config = null) {
  if (!messages || !messages.length) return;
  if (!config) config = await getRuntimeConfig();

  const firstMessage = messages[0];
  const chatId = String(firstMessage.chat.id);
  const forwardChatId = config.forward_chat_id || getAdminUid();

  const isBlocked = await isUserBlocked(chatId);
  if (isBlocked) {
    await incrementStat('blocked-user-message');
    return;
  }

  let blockedResult = null;
  let violatingMessage = null;
  for (const msg of messages) {
    const match = await findBlockedKeyword(msg);
    if (match && match.matched) {
      blockedResult = match;
      violatingMessage = msg;
      break;
    }
  }

  if (blockedResult) {
    const targetMsg = violatingMessage || firstMessage;
    const violation = await recordKeywordViolation(targetMsg, blockedResult.rule);
    if (config.auto_block && violation.count >= config.violation_limit) {
      await setUserBlocked(chatId, true);
      await incrementStat('keyword-auto-blocked');
    }
    await notifyKeywordBlocked(targetMsg, blockedResult, violation, config);
    if (config.notice_user) {
      const text = violation.count >= config.violation_limit
        ? '多次发送不能转达的内容，这里暂时不能继续留言了喵。'
        : '这条留言含有暂时不能转达的词，人偶先收起来了喵。';
      return sendCooldownPlainText(chatId, `keyword-notice-${chatId}`, text, getCommandWarningCooldownMs());
    }
    return;
  }

  if (!forwardChatId) {
    console.log(JSON.stringify({ error: 'no-forward-chat-id-configured', chatId }));
    return;
  }

  let targetThreadId = config.forward_thread_id || null;

  // Auto-create Forum Topic if enabled for supergroup
  if (config.enable_forum_topics && forwardChatId.startsWith('-')) {
    let topicId = await getGuestTopicId(chatId);
    if (!topicId) {
      const topicName = `${buildUserName(firstMessage.from || {})} (${chatId})`.slice(0, 128);
      const createRes = await createForumTopic({
        chat_id: forwardChatId,
        name: topicName,
      });
      if (createRes.ok && createRes.result?.message_thread_id) {
        topicId = createRes.result.message_thread_id;
        await setGuestTopicId(chatId, topicId);
      }
    }
    if (topicId) {
      targetThreadId = topicId;
    }
  }

  const threadParam = targetThreadId ? { message_thread_id: targetThreadId } : {};
  const guestTag = await getGuestTag(chatId);
  const infoReq = await sendMarkdown(
    forwardChatId,
    buildMessageInfo(firstMessage, messages.length, guestTag),
    threadParam,
  );
  if (infoReq.ok) {
    await rememberMessageMap(infoReq.result.message_id, chatId);
  }

  let deliveredAny = false;
  for (let i = 0; i < messages.length; i++) {
    const msg = messages[i];
    const isLast = i === messages.length - 1;
    const extra = {
      ...threadParam,
      ...(isLast ? { reply_markup: adminMessageKeyboard() } : {}),
    };

    const copyReq = await copyMessage({
      chat_id: forwardChatId,
      from_chat_id: msg.chat.id,
      message_id: msg.message_id,
      ...extra,
    });

    if (copyReq.ok) {
      deliveredAny = true;
      await rememberMessageMap(copyReq.result.message_id, chatId);
      continue;
    }

    const forwardReq = await forwardMessage({
      chat_id: forwardChatId,
      from_chat_id: msg.chat.id,
      message_id: msg.message_id,
      ...threadParam,
    });

    if (forwardReq.ok) {
      deliveredAny = true;
      await rememberMessageMap(forwardReq.result.message_id, chatId);
      continue;
    }

    await sendMarkdown(
      forwardChatId,
      [
        '*人偶转达失败*',
        mdLine('用户ID', chatId),
        mdLine('错误', forwardReq.description || copyReq.description || 'Unknown error'),
      ].join('\n'),
      threadParam,
    );
  }

  if (deliveredAny) {
    await handleGuestDelivered(messages[messages.length - 1], config);
  }
}
async function handleGuestDelivered(message, config = null) {
  if (!config) config = await getRuntimeConfig();
  const chatId = String(message.chat.id);

  if (config.away_mode) {
    const awayMsg = config.away_message || '人偶现在外出中，稍后会尽快回复您的留言喵。';
    await sendCooldownPlainText(chatId, `away-notice-${chatId}`, awayMsg, 1800000); // 30 minutes cooldown
  }

  await sendCooldownPlainText(
    chatId,
    `deliver-ack-${chatId}`,
    '留言已经交给管理人啦，人偶会乖乖等回信喵。',
    getUserAckCooldownMs(),
  );
  await handleNotify(message, config);
}
async function handleNotify(message, config = null) {
  if (!config) config = await getRuntimeConfig();
  const chatId = String(message.chat.id);
  const alertChatId = config.alert_chat_id || getAdminUid();
  if (!alertChatId) return;

  const extra = config.alert_thread_id ? { message_thread_id: config.alert_thread_id } : {};

  if (await isFraud(chatId)) {
    return sendMarkdown(alertChatId, `*诈骗库命中*\n${mdLine('UID', chatId)}`, extra);
  }

  if (!config.enable_notify) return;

  const lastMsgTime = await kvGetJson(`lastmsg-${chatId}`, 0);
  if (!lastMsgTime || Date.now() - Number(lastMsgTime) > NOTIFY_INTERVAL) {
    await nfd.put(`lastmsg-${chatId}`, String(Date.now()));
    const notification = await fetchTextOrDefault(getNotificationUrl(), DEFAULT_NOTIFICATION);
    return sendMarkdown(alertChatId, notification, extra);
  }
}

